// ========== 标签词表 ==========
const TAG_VOCAB = ['邀约','吃饭','暧昧','表白','想念','生气','冷淡','拒绝','加班','日常','关心','试探','自嘲','夸赞','道歉','告别','早安','晚安','下雨','节日','工作','学习','见面','约会','幽默','文艺']

// ========== 关键词提取 ==========
function extractKeywords(text) {
  const keywords = []
  for (const tag of TAG_VOCAB) {
    if (text.includes(tag)) keywords.push(tag)
  }
  return keywords
}

// ========== 随机取卡（支持关键词筛选） ==========
function pickRandomLines(count, category, filterKeywords, isMinor) {
  let pool = category ? SEED_DATA.filter(d => d.category === category) : SEED_DATA
  if (isMinor) pool = filterSeedForMinor(pool)

  // 有关键词时，优先匹配 tag，匹配不到再从全量随机
  if (filterKeywords && filterKeywords.length > 0) {
    const matched = pool.filter(d => {
      if (!d.tags || d.tags.length === 0) return false
      return filterKeywords.some(kw => d.tags.includes(kw))
    })
    // 匹配到的优先，不够的从全量补
    if (matched.length >= count) {
      pool = matched
    } else if (matched.length > 0) {
      const rest = pool.filter(d => !matched.includes(d))
      pool = [...matched, ...rest]
    }
  }

  // 随机选
  const picked = []
  const used = new Set()
  for (let i = 0; i < count && used.size < pool.length; i++) {
    let idx
    do { idx = Math.floor(Math.random() * pool.length) } while (used.has(idx))
    used.add(idx)
    picked.push(pool[idx])
  }
  return picked
}

// ========== DB 操作 ==========

async function seedCollection() {
  let existingCount = 0
  try {
    const { data: existing } = await db.collection(COLLECTION).limit(1).get()
    if (existing && existing.length > 0) return { seeded: false, message: '已有数据', existingCount: existing.length }
  } catch (e) {
    if (!String(e.message || '').includes('not exist')) throw e
  }
  const docs = SEED_DATA.map((item, index) => ({
    _id: `pet_${item.category}_${index}`, category: item.category, text: item.text,
    tags: item.tags || [], createdAt: new Date()
  }))
  const batchSize = 200
  let inserted = 0
  for (let i = 0; i < docs.length; i += batchSize) {
    const batch = docs.slice(i, i + batchSize)
    await Promise.all(batch.map(async (doc) => {
      try { await db.collection(COLLECTION).add(doc) } catch { await db.collection(COLLECTION).doc(doc._id).set(doc).catch(() => {}) }
    }))
    inserted += batch.length
  }
  return { seeded: true, inserted }
}

async function getRandomLine(category) {
  const categoryFilter = category && ['humor', 'literary'].includes(category)
  try {
    const query = categoryFilter
      ? db.collection(COLLECTION).where({ category }).limit(20).get()
      : db.collection(COLLECTION).limit(20).get()
    const { data } = await query
    if (!data || data.length === 0) return null
    const pick = data[Math.floor(Math.random() * data.length)]
    return { _id: pick._id, category: pick.category, text: pick.text }
  } catch (e) {
    const list = categoryFilter ? SEED_DATA.filter(d => d.category === category) : SEED_DATA
    if (list.length === 0) return null
    const pick = list[Math.floor(Math.random() * list.length)]
    return { _id: `seed_${Math.random().toString(36).slice(2)}`, category: pick.category, text: pick.text }
  }
}

// ========== AI 调用 ==========

/** 返回所有可用模型，按优先级排序（默认模型排第一），跳过无 key 或超额的 */
function resolveAvailableModels(settings) {
  if (settings?.settingsVersion === 2 && Array.isArray(settings?.aiModels) && settings.aiModels.length > 0) {
    const defaultId = settings.aiDefaultModelId || 'default'
    const sorted = [...settings.aiModels].sort((a, b) => {
      if (a.id === defaultId) return -1
      if (b.id === defaultId) return 1
      return 0
    })
    return sorted
      .filter(m => {
        const key = String(m.apiKey || '').trim()
        const quota = Number(m.quota || 0)
        const used = Number(m.tokensUsed || 0)
        return key && (quota === 0 || used < quota)
      })
      .map(m => ({
        id: m.id,
        enabled: Boolean(settings.aiEnabled),
        apiKey: String(m.apiKey || '').trim(),
        baseUrl: String(m.baseUrl || '').trim() || 'https://api.openai.com/v1',
        model: String(m.model || '').trim() || 'gpt-4o-mini',
        provider: String(m.provider || 'openai-compatible').trim().toLowerCase(),
        quota: Number(m.quota || 0),
        tokensUsed: Number(m.tokensUsed || 0)
      }))
  }
  // Legacy single-model
  return [{
    id: 'default',
    enabled: Boolean(settings?.aiEnabled),
    apiKey: String(settings?.aiApiKey || '').trim(),
    baseUrl: String(settings?.aiBaseUrl || '').trim() || 'https://api.openai.com/v1',
    model: String(settings?.aiModel || '').trim() || 'gpt-4o-mini',
    provider: String(settings?.aiProvider || 'openai-compatible').trim().toLowerCase(),
    quota: 0,
    tokensUsed: 0
  }].filter(m => m.apiKey)
}

/** 取第一个可用模型（兼容旧逻辑） */
function normalizeAISettingsForReply(settings) {
  const models = resolveAvailableModels(settings)
  return models[0] || {
    enabled: Boolean(settings?.aiEnabled),
    apiKey: '',
    baseUrl: 'https://api.openai.com/v1',
    model: 'gpt-4o-mini',
    provider: 'openai-compatible'
  }
}

/** 记录模型 token 消耗 */
async function recordModelTokenUsage(modelId, tokens, usage) {
  if (!modelId) return
  try {
    const doc = await db.collection('system_settings').where({ scope: 'global', key: 'ai' }).limit(1).get().catch(() => null)
    const settings = doc?.data?.[0]
    const models = settings?.aiModels
    if (!Array.isArray(models)) return
    const idx = models.findIndex(m => m.id === modelId)
    if (idx < 0) return
    const consumed = (usage?.total_tokens || tokens || 0)
    const current = Number(models[idx].tokensUsed || 0)
    await db.collection('system_settings').doc(settings._id).update({
      [`aiModels.${idx}.tokensUsed`]: current + consumed
    }).catch(() => {})
  } catch {}
}

/** 多模型重试包装：依次尝试每个模型，成功则返回，全失败则返回最后一个错误 */
async function tryWithModelFallback(fn) {
  const settingsRes = await db.collection('system_settings').where({ scope: 'global', key: 'ai' }).limit(1).get().catch(() => null)
  const settings = settingsRes?.data?.[0]
  const models = resolveAvailableModels(settings || {})
  if (models.length === 0) return { success: false, message: '无可用 AI 模型，请检查配置' }

  let lastError = null
  for (const model of models) {
    try {
      const result = await fn(model)
      if (result?.success !== false) return result
      lastError = result
    } catch (e) {
      lastError = { success: false, message: e?.message || 'AI 调用异常' }
    }
  }
  return lastError || { success: false, message: '所有 AI 模型均不可用' }
}

function aiHttpRequest(urlStr, body, timeoutMs, apiKey) {
  return new Promise((resolve, reject) => {
    const u = new URL(urlStr)
    const transport = u.protocol === 'http:' ? http : https
    const payload = JSON.stringify(body)
    const req = transport.request({
      protocol: u.protocol, hostname: u.hostname, port: u.port || undefined,
      path: `${u.pathname}${u.search}`, method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(payload), Authorization: `Bearer ${apiKey}` }
    }, (res) => {
      const chunks = []
      res.on('data', c => chunks.push(Buffer.isBuffer(c) ? c : Buffer.from(c)))
      res.on('end', () => {
        const text = Buffer.concat(chunks).toString('utf8')
        resolve({ ok: res.statusCode >= 200 && res.statusCode < 300, status: res.statusCode, text: () => Promise.resolve(text), json: () => Promise.resolve(JSON.parse(text)) })
      })
    })
    req.setTimeout(timeoutMs, () => req.destroy(new Error('REPLY_AI_TIMEOUT')))
    req.on('error', reject)
    req.write(payload)
    req.end()
  })
}

// ========== reply (单句，兼容旧版) ==========

async function generateReply(eventDesc, eventType, userId, isMinor) {
  const settingsDoc = await db.collection('system_settings').where({ scope: 'global', key: 'ai' }).limit(1).get().catch(() => ({ data: [] }))
  const settings = settingsDoc.data?.[0]
  if (!settings) return { success: false, message: 'AI 未配置' }
  const ai = normalizeAISettingsForReply(settings)
  const cfg = getPetSpeakConfig(settings, 'reply', { isMinor: Boolean(isMinor) })
  if (!ai.enabled || !ai.apiKey) return { success: false, message: 'AI 未启用' }

  if (userId) {
    const bal = await checkReplyBalance(userId)
    if (!bal.ok) return { success: false, ...bal, message: bal.message || '余额不足' }
  }

  const inspirations = pickRandomLines(4, null, null, isMinor)
  const inspText = inspirations.map((l, i) => `${i + 1}. [${l.category === 'humor' ? '幽默' : '文艺'}] ${l.text}`).join('\n')
  const toneGuide = {
    positive: '对方释放了积极信号，回复可以热情、俏皮、适当撩一下。',
    risk: '对方可能在回避或冷淡，回复要轻松、不卑微、略带幽默自嘲，不要追问。',
    verification: '对方的话需要验证，回复要巧妙试探、不直接质问，带幽默感。',
    note: '普通互动，回复自然轻松、带风趣，不要用力过猛。'
  }
  const tone = toneGuide[eventType] || toneGuide.note
  const messages = [
    { role: 'system', content: '你是恋爱对话教练，帮用户生成一句自然、幽默、适合当前语境的回复。只输出一句回复（20-50字），不要解释、不要编号、不要引号。' },
    { role: 'user', content: `场景：对方做了/说了这样一件事：「${eventDesc.slice(0, 160)}」\n${tone}\n\n参考风格（吸收后改写）：\n${inspText}\n\n根据场景生成一句自然回复：` }
  ]
  const baseUrl = ai.baseUrl.replace(/\/+$/, '')
  const urls = [`${baseUrl}/v1/chat/completions`, `${baseUrl}/chat/completions`]
  let response = null
  for (const url of urls) { response = await aiHttpRequest(url, { model: ai.model, messages, temperature: cfg.temperature, max_tokens: cfg.maxTokens }, REPLY_TIMEOUT_MS, ai.apiKey); if (response.status !== 404) break }
  if (!response?.ok) {
    const errText = await response?.text().catch(() => '')
    return { success: false, message: `AI 返回 ${response?.status || 0}${errText ? ' / ' + errText.slice(0, 100) : ''}` }
  }
  const data = await response.json()
  const reply = (data?.choices?.[0]?.message?.content || '').trim().replace(/^["'「『"']+|["'」』"']+$/g, '').replace(/^回复[：:]\s*/i, '')
  if (userId) await recordReplyTokenUsage(userId, getUsageTotalTokens(data?.usage, REPLY_PAIR_EST_TOKENS), ai.model, data?.usage)
  return { success: true, reply: reply || '（AI 未生成有效回复）', inspirations: inspirations.map(l => ({ category: l.category, text: l.text })) }
}

// ========== replyPair (双句) ==========

async function checkPetTokenBalance(userId, estTokens = REPLY_PAIR_EST_TOKENS, accessFeature = PET_REPLY_ACCESS_FEATURE) {
  try {
    // 功能 + Token 门控（v3.2）
    const access = await checkFeatureAccess(db, userId, accessFeature)
    if (!access.allowed) return { ok: false, code: 'FEATURE_NOT_AVAILABLE', message: access.reason, balance: 0, required: 0 }
    const tokCheck = await checkTokenBalance(db, userId, estTokens)
    const monthlyRemaining = Number(tokCheck.monthlyRemaining || 0)
    const extraTokens = Number(tokCheck.extraTokens || 0)
    const balance = monthlyRemaining + extraTokens
    if (!tokCheck.ok) {
      return {
        ...tokCheck,
        ok: false,
        balance,
        required: tokCheck.required || estTokens
      }
    }

    return {
      ...tokCheck,
      ok: true,
      balance,
      required: tokCheck.required || estTokens
    }
  } catch (e) {
    console.error('checkPetTokenBalance error:', e)
    return { ok: false, code: 'TOKEN_CHECK_FAILED', message: 'Token 校验失败，请稍后重试', balance: 0, required: estTokens }
  }
}

async function checkReplyBalance(userId, estTokens = REPLY_PAIR_EST_TOKENS) {
  return checkPetTokenBalance(userId, estTokens, PET_REPLY_ACCESS_FEATURE)
}

function isTokenBalanceError(result) {
  return result && ['TOKEN_INSUFFICIENT', 'INSUFFICIENT_BALANCE'].includes(result.code)
}

async function recordPetTokenUsage(userId, realTokens, model, usage, feature = PET_REPLY_USAGE_FEATURE) {
  try {
    await recordTokenUsage(db, {
      userId,
      feature,
      provider: 'openai-compatible',
      model: model || '',
      usage: buildUsageWithFallback(usage, realTokens || REPLY_PAIR_EST_TOKENS)
    })
  } catch (e) { console.error('recordReplyTokenUsage error:', e) }
}

async function recordReplyTokenUsage(userId, realTokens, model, usage) {
  return recordPetTokenUsage(userId, realTokens, model, usage, PET_REPLY_USAGE_FEATURE)
}

const REPLY_TONES = {
  humor: {
    label: '幽默轻松',
    instruction: '轻松、有梗、接地气，可以带一点俏皮，但不要油腻、不要阴阳怪气。'
  },
  flirty: {
    label: '暧昧轻撩',
    instruction: '轻撩、有来回、有分寸，制造互动感；不要性暗示、不要逼表态、不要装可怜、不要情绪勒索。'
  },
  sincere: {
    label: '真诚直接',
    instruction: '表达清楚、直接、舒服，不卑微、不攻击、不绕弯，适合认真回应或确认意图。'
  },
  literary: {
    label: '委婉文艺',
    instruction: '委婉、含蓄、有画面感，可以有一点氛围，但不要堆砌辞藻、不要像表白小作文。'
  }
}

const REPLY_TONE_KEYS = Object.keys(REPLY_TONES)

function cleanReplyText(value) {
  return String(value || '').trim().replace(/^["'「『"']+|["'」』"']+$/g, '')
}

function buildReplySystemPrompt(baseSystemPrompt, jsonShape) {
  const base = String(baseSystemPrompt || '').trim()
  const instruction = `返回严格 JSON，不要任何解释文字。JSON 格式：${jsonShape}`
  if (!base) return `你是恋爱对话教练。${instruction} 每句15-40字，自然、尊重、有边界。`
  if (base.includes('{jsonShape}')) return base.replace('{jsonShape}', jsonShape)
  return `${base}\n\n${instruction}`
}

async function generateReplyPair(scene, content, userId, tone, safetyContext) {
  if (userId) {
    const balCheck = await checkReplyBalance(userId)
    if (!balCheck.ok) return { success: false, ...balCheck, message: balCheck.message || '余额不足，请充值' }
  }

  const settingsRes = await db.collection('system_settings').where({ scope: 'global', key: 'ai' }).limit(1).get().catch(() => null)
  const settings = settingsRes?.data?.[0] || {}
  const replyModuleKey = scene === 'active' ? 'replyActive' : 'reply'
  const cfg = getPetSpeakConfig(settings, replyModuleKey, safetyContext)

  const keywords = extractKeywords(content)
  const humorPicks = pickRandomLines(3, 'humor', keywords)
  const literaryPicks = pickRandomLines(3, 'literary', keywords)
  const inspirations = [...humorPicks, ...literaryPicks]
  const inspText = inspirations.map((l, i) => `${i + 1}. [${l.category === 'humor' ? '幽默' : '文艺'}] ${l.text}`).join('\n')

  const targetTone = REPLY_TONE_KEYS.includes(tone) ? tone : ''
  const toneLines = (targetTone ? [targetTone] : REPLY_TONE_KEYS)
    .map(key => `- ${key}（${REPLY_TONES[key].label}）：${REPLY_TONES[key].instruction}`)
    .join('\n')
  const jsonShape = targetTone
    ? `{"variants":{"${targetTone}":"一句可直接发送的话"}}`
    : '{"variants":{"humor":"幽默轻松","flirty":"暧昧轻撩","sincere":"真诚直接","literary":"委婉文艺"}}'
  const baseSystemPrompt = cfg.systemPrompt || DEFAULT_PET_SPEAK_CONFIG.reply.systemPrompt
  const systemPrompt = buildReplySystemPrompt(baseSystemPrompt, jsonShape)
  let userPrompt = ''
  if (scene === 'active') {
    userPrompt = `用户想主动对心仪对象说一句话。\n想表达的意思：${content.slice(0, 200)}\n\n参考话术：\n${inspText}\n\n请按以下语气生成：\n${toneLines}`
  } else {
    userPrompt = `对方说了一句话，用户不知道怎么回。\n对方说的话：${content.slice(0, 200)}\n\n参考话术：\n${inspText}\n\n请按以下语气生成回复：\n${toneLines}`
  }

  return tryWithModelFallback(async (model) => {
    const baseUrl = model.baseUrl.replace(/\/+$/, '')
    const urls = [`${baseUrl}/v1/chat/completions`, `${baseUrl}/chat/completions`]
    let response = null
    for (const url of urls) {
      response = await aiHttpRequest(url, {
        model: model.model, messages: [{ role: 'system', content: systemPrompt }, { role: 'user', content: userPrompt }],
        temperature: cfg.temperature, max_tokens: targetTone ? Math.min(cfg.maxTokens, 160) : cfg.maxTokens, response_format: { type: 'json_object' }
      }, REPLY_TIMEOUT_MS, model.apiKey)
      if (response.status !== 404) break
    }
    if (!response?.ok) {
      return { success: false, message: `AI 返回 ${response?.status || 0}` }
    }

    const data = await response.json()
    var raw = data?.choices?.[0]?.message?.content || ''
    // strip markdown code fences
    raw = raw.replace(/^```(?:json)?\s*\n?/i, '').replace(/\n?```\s*$/i, '').trim()
    var parsed = (function () { try { return JSON.parse(raw) } catch (e) { return null } })()
    var parsedVariants = (parsed && parsed.variants && typeof parsed.variants === 'object') ? parsed.variants : {}
    var variants = {}
    REPLY_TONE_KEYS.forEach(function (key) {
      var value = cleanReplyText(parsedVariants[key] || (parsed && parsed[key]))
      if (value) variants[key] = value
    })
    // Also accept Chinese tone labels, whether they appear alone or mixed with English keys.
    REPLY_TONE_KEYS.forEach(function (key) {
      if (variants[key]) return
      var labelKey = REPLY_TONES[key].label
      var value = cleanReplyText(parsedVariants[labelKey] || (parsed && parsed[labelKey]))
      if (value) variants[key] = value
    })
    var directText = parsed && cleanReplyText(parsed.reply || parsed.text || parsed.content || parsed.message || parsed.answer)
    if (directText) {
      variants[targetTone || 'sincere'] = directText
    }
    // fallback: if still empty, try raw text or any variant value
    if (Object.keys(variants).length === 0 && !parsed) {
      variants[targetTone || 'sincere'] = cleanReplyText(raw.slice(0, 80)) || raw.slice(0, 40)
    }
    if (!variants[targetTone || 'sincere'] && parsed && parsed.reply) variants[targetTone || 'sincere'] = cleanReplyText(parsed.reply)
    if (!variants.literary && parsed && parsed.alternative) variants.literary = cleanReplyText(parsed.alternative)
    if (Object.keys(variants).length === 0) {
      var anyValue = Object.values(parsedVariants).find(function (v) { return typeof v === 'string' && cleanReplyText(v) })
      if (anyValue) variants[targetTone || 'sincere'] = cleanReplyText(anyValue)
    }
    if (Object.keys(variants).length === 0 && parsed && typeof parsed === 'object') {
      var topLevelValue = Object.keys(parsed).map(function (key) { return parsed[key] }).find(function (v) { return typeof v === 'string' && cleanReplyText(v) })
      if (topLevelValue) variants[targetTone || 'sincere'] = cleanReplyText(topLevelValue)
    }
    var fallbackText = Object.values(variants).find(Boolean) || '（AI 暂未生成有效回复）'
    var reply = (targetTone && variants[targetTone]) || variants.sincere || variants.humor || fallbackText
    var alternative = variants.literary || fallbackText
    var realTokens = getUsageTotalTokens(data?.usage, REPLY_PAIR_EST_TOKENS)

    if (userId) await recordReplyTokenUsage(userId, realTokens, model.model, data?.usage)
    await recordModelTokenUsage(model.id, realTokens, data?.usage)

    return {
      success: true,
      variants,
      reply,
      alternative,
      inspirations: inspirations.map(l => ({ category: l.category, text: l.text })),
      tokensUsed: realTokens
    }
  })
}

// ========== tagLines ==========

async function tagOneBatch(ai, items, startIndex, cfg) {
  const linesText = items.map((item, i) => `${i}. ${item.text}`).join('\n')
  const systemPrompt = `你是内容分类助手。给每条话术打2-4个场景标签，只从以下词表选择：${TAG_VOCAB.join(',')}。返回JSON：{"results":[{"index":0,"tags":["标签1","标签2"]},...]}`
  const userPrompt = `话术列表：\n${linesText}\n\n请给每条打标签，返回JSON对象。`
  const baseUrl = ai.baseUrl.replace(/\/+$/, '')
  const urls = [`${baseUrl}/v1/chat/completions`, `${baseUrl}/chat/completions`]
  let response = null
  for (const url of urls) {
    response = await aiHttpRequest(url, { model: ai.model, messages: [{ role: 'system', content: systemPrompt }, { role: 'user', content: userPrompt }], temperature: cfg.temperature, max_tokens: cfg.maxTokens, response_format: { type: 'json_object' } }, REPLY_TIMEOUT_MS, ai.apiKey)
    if (response.status !== 404) break
  }
  if (!response?.ok) {
    const errText = await response?.text().catch(() => '')
    throw new Error(`AI 返回 ${response?.status} / ${errText.slice(0, 100)}`)
  }
  const data = await response.json()
  const raw = data?.choices?.[0]?.message?.content || ''
  let tagResults
  try {
    const parsed = JSON.parse(raw)
    tagResults = Array.isArray(parsed?.results) ? parsed.results : Array.isArray(parsed) ? parsed : []
  } catch {
    const m = raw.match(/\[[\s\S]*\]/)
    if (m) try { tagResults = JSON.parse(m[0]) } catch { tagResults = [] }
    else tagResults = []
  }
  const tagged = []
  for (const item of tagResults) {
    if (typeof item.index === 'number' && Array.isArray(item.tags)) {
      const src = items[item.index]
      if (src) tagged.push({ index: startIndex + item.index, tags: item.tags.filter(t => TAG_VOCAB.includes(t)).slice(0, 5) })
    }
  }
  for (let i = 0; i < items.length; i++) {
    if (!tagged.find(t => t.index === startIndex + i)) tagged.push({ index: startIndex + i, tags: [] })
  }
  return { tagged, usage: data?.usage }
}

async function tagLinesLoop(startIndex, count, userId) {
  const settingsDoc = await db.collection('system_settings').where({ scope: 'global', key: 'ai' }).limit(1).get().catch(() => ({ data: [] }))
  const settings = settingsDoc.data?.[0]
  if (!settings) return { success: false, message: 'AI 未配置' }
  const ai = normalizeAISettingsForReply(settings)
  if (!ai.enabled || !ai.apiKey) return { success: false, message: 'AI 未启用' }
  const cfg = getPetSpeakConfig(settings, 'lineTagging')
  const endTarget = Math.min(startIndex + count, SEED_DATA.length)
  const BATCH_SIZE = 20
  const allTagged = []
  let current = startIndex
  while (current < endTarget) {
    if (userId) {
      const bal = await checkReplyBalance(userId, LINE_TAGGING_EST_TOKENS)
      if (!bal.ok) return { success: false, ...bal, message: bal.message || '余额不足，请先充值' }
    }
    const batch = SEED_DATA.slice(current, Math.min(current + BATCH_SIZE, endTarget))
    const { tagged, usage } = await tagOneBatch(ai, batch, current, cfg)
    allTagged.push(...tagged)
    if (userId) await recordPetTokenUsage(userId, getUsageTotalTokens(usage, LINE_TAGGING_EST_TOKENS), ai.model, usage, PET_TAGGING_USAGE_FEATURE)
    current += batch.length
  }
  return { success: true, tagged: allTagged, startIndex, endIndex: endTarget, total: SEED_DATA.length }
}

// ========== QA 去重 & AI 生成 ==========

async function getUserQAHistory(userId) {
  if (!userId) return null
  try {
    const { data } = await db.collection(QA_HISTORY_COLLECTION).doc(userId).get().catch(() => ({ data: [] }))
    if (data && data.length > 0) return data[0]
  } catch {}
  return null
}

async function updateUserQAHistory(userId, newTexts, source) {
  if (!userId) return
  const now = new Date()
  try {
    const existing = await getUserQAHistory(userId)
    if (existing) {
      const seenTexts = [...new Set([...newTexts, ...(existing.seenTexts || [])])].slice(0, QA_MAX_HISTORY)
      await db.collection(QA_HISTORY_COLLECTION).doc(userId).update({
        seenTexts,
        seedPickCount: source === 'ai' ? (existing.seedPickCount || 0) : (existing.seedPickCount || 0) + newTexts.length,
        aiGenCount: source === 'ai' ? (existing.aiGenCount || 0) + newTexts.length : (existing.aiGenCount || 0),
        updatedAt: now
      }).catch(() => {})
    } else {
      await db.collection(QA_HISTORY_COLLECTION).add({
        _id: userId,
        seenTexts: newTexts,
        seedPickCount: source === 'seed' ? newTexts.length : 0,
        aiGenCount: source === 'ai' ? newTexts.length : 0,
        updatedAt: now
      }).catch(() => {})
    }
  } catch {}
}

async function generateQAByAI(content, userId) {
  try {
    const settingsRes = await db.collection('system_settings').where({ scope: 'global', key: 'ai' }).limit(1).get().catch(() => null)
    const settings = settingsRes?.data?.[0]
    const ai = normalizeAISettingsForReply(settings || {})
    if (!ai.enabled || !ai.apiKey) return null
    const cfg = getPetSpeakConfig(settings || {}, 'qaStrategy')

    if (userId) {
      const bal = await checkReplyBalance(userId, QA_GEN_EST_TOKENS)
      if (!bal.ok) return null
    }

    const baseUrl = ai.baseUrl.replace(/\/+$/, '')
    const urls = [`${baseUrl}/v1/chat/completions`, `${baseUrl}/chat/completions`]
    const systemPrompt = `你是撩人话术生成器。根据用户想表达的场景，生成1条幽默俏皮的一问一答式撩人情话。格式严格用 | 分隔问和答，15-30字。例如：在干嘛？|在想你。不要输出任何解释，只输出问答。`

    let lastError = null
    for (const url of urls) {
      try {
        const resp = await aiHttpRequest(url, {
          model: ai.model,
          messages: [
            { role: 'system', content: systemPrompt },
            { role: 'user', content: `场景：${content.slice(0, 200)}` }
          ],
          temperature: cfg.temperature,
          max_tokens: cfg.maxTokens
        }, REPLY_TIMEOUT_MS, ai.apiKey)

        if (resp.status === 404) continue
        const data = await resp.json().catch(() => null)
        if (!data?.choices?.[0]?.message?.content) continue

        const raw = data.choices[0].message.content.trim()
        const match = raw.match(/[^|]+[|][^|]+/)
        if (!match) continue

        const text = match[0].trim()
        if (userId) await recordPetTokenUsage(userId, getUsageTotalTokens(data?.usage, QA_GEN_EST_TOKENS), ai.model, data?.usage, PET_QA_USAGE_FEATURE)
        return { text, aiGenerated: true }
      } catch (e) {
        lastError = e
        continue
      }
    }
    if (lastError) console.error('generateQAByAI error:', lastError?.message)
  } catch (e) {
    console.error('generateQAByAI error:', e?.message)
  }
  return null
}

async function pickQAWithDedup(content, userId) {
  const keywords = extractKeywords(content)
  const allQA = SEED_DATA.filter(d => d.category === 'qa')

  // 按关键词匹配度排序
  const scored = allQA.map(d => {
    let score = 0
    if (keywords.length > 0 && d.tags) {
      const matchCount = keywords.filter(kw => d.tags.includes(kw)).length
      score = matchCount
    }
    return { ...d, score }
  }).sort((a, b) => b.score - a.score)

  // 查历史
  const history = await getUserQAHistory(userId)
  const seenTexts = history?.seenTexts || []
  const seenSet = new Set(seenTexts)
  const aiGenCount = history?.aiGenCount || 0
  const seedPickCount = history?.seedPickCount || 0

  // 优先未看过的
  const fresh = scored.filter(d => !seenSet.has(d.text))
  const stale = scored.filter(d => seenSet.has(d.text))

  let picked = []
  let aiLine = null

  // 决定要不要 AI 生成：累计 >= QA_AI_TRIGGER_COUNT 次，且每 QA_AI_INTERVAL 触发一次
  const shouldAI = seedPickCount >= QA_AI_TRIGGER_COUNT && (seedPickCount % QA_AI_INTERVAL === 0)

  if (shouldAI && userId) {
    aiLine = await generateQAByAI(content, userId)
  }

  // 从新鲜池里挑
  const freshCount = aiLine ? 1 : 2
  for (let i = 0; i < freshCount && picked.length < freshCount; i++) {
    if (fresh.length - i > 0) {
      const idx = Math.floor(Math.random() * Math.min(fresh.length, freshCount * 3))
      if (!picked.includes(fresh[idx])) picked.push(fresh[idx])
    }
  }
  // 不够从 stale 补
  if (picked.length < freshCount) {
    for (let i = 0; i < stale.length && picked.length < freshCount; i++) {
      const idx = Math.floor(Math.random() * stale.length)
      if (!picked.includes(stale[idx])) picked.push(stale[idx])
    }
  }
  // 还是不够从全量补
  while (picked.length < freshCount) {
    const idx = Math.floor(Math.random() * scored.length)
    if (!picked.includes(scored[idx])) picked.push(scored[idx])
  }

  const lines = picked.map(d => ({ text: d.text }))

  // 拼入 AI 生成的
  if (aiLine) {
    lines.unshift({ text: aiLine.text, aiGenerated: true })
  }

  // 记录历史
  const newTexts = lines.map(l => l.text)
  await updateUserQAHistory(userId, aiLine ? [aiLine.text] : newTexts, aiLine ? 'ai' : 'seed')

  return { lines, freshCount: fresh.length, total: scored.length, aiMixed: !!aiLine }
}

// ========== QA 语义标准化 ==========

async function normalizeQASelfReply() {
  const allQA = SEED_DATA.filter(d => d.category === 'qa')
  if (allQA.length === 0) return { normalized: 0, message: '无 QA 数据' }

  const settingsRes = await db.collection('system_settings').where({ scope: 'global', key: 'ai' }).limit(1).get().catch(() => null)
  const settings = settingsRes?.data?.[0]
  const ai = normalizeAISettingsForReply(settings || {})
  if (!ai.enabled || !ai.apiKey) return { success: false, message: 'AI 配置未启用或缺少 API Key' }

  const systemPrompt = `你是撩人情话编辑。把每条话术转为"自问自答"格式：用户先抛一句话（问或陈述），对方无论回什么，用户接着甩出撩人答案。用 | 分隔两个部分。规则：
1. 第一个部分：用户说的话（问句或陈述句），不加对方的预期回复
2. 第二个部分：用户接着说的撩人答案（不包含对方的回复内容）
3. 保持原文风格和字数
4. 两个部分各自独立完整，能直接拿来用
5. 只输出 JSON 数组，每项 {"index": 序号, "text": "问|答"}`

  const cfg = getPetSpeakConfig(settings || {}, 'qaMaintenance')
  const BATCH_SIZE = 30
  const results = []

  for (let start = 0; start < allQA.length; start += BATCH_SIZE) {
    const batch = allQA.slice(start, start + BATCH_SIZE)
    const items = batch.map((d, i) => `${start + i}: ${d.text}`).join('\n')
    const userPrompt = `将以下话术转为自问自答格式，只返回 JSON：\n${items}`

    const baseUrl = ai.baseUrl.replace(/\/+$/, '')
    const urls = [`${baseUrl}/v1/chat/completions`, `${baseUrl}/chat/completions`]

    let batchDone = false
    for (const url of urls) {
      if (batchDone) break
      try {
        const resp = await aiHttpRequest(url, {
          model: ai.model,
          messages: [
            { role: 'system', content: systemPrompt },
            { role: 'user', content: userPrompt }
          ],
          temperature: cfg.temperature,
          max_tokens: cfg.maxTokens
        }, REPLY_TIMEOUT_MS * 2, ai.apiKey)

        if (resp.status === 404) continue
        const data = await resp.json().catch(() => null)
        const raw = data?.choices?.[0]?.message?.content || ''
        const jsonMatch = raw.match(/\[[\s\S]*\]/)
        if (!jsonMatch) continue

        const parsed = JSON.parse(jsonMatch[0])
        parsed.forEach(item => {
          if (typeof item.index === 'number' && typeof item.text === 'string') {
            const parts = item.text.split('|').map(s => s.trim())
            if (parts.length === 2 && parts[0] && parts[1]) {
              results.push({ index: item.index, text: item.text, original: allQA[item.index]?.text || '' })
            }
          }
        })
        batchDone = true
      } catch (e) {
        console.error(`normalizeQASelfReply batch ${start} error:`, e?.message)
      }
    }

    if (!batchDone) {
      batch.forEach((d, i) => {
        results.push({ index: start + i, text: d.text, original: d.text, note: 'AI 处理失败，保留原样' })
      })
    }
  }

  // 存到 DB，避免返回值过大
  const batchId = `qa_norm_${Date.now()}`
  try {
    await db.collection('qa_normalize_results').add({
      _id: batchId,
      total: allQA.length,
      normalized: results.filter(r => !r.note).length,
      results,
      createdAt: new Date()
    })
  } catch {}

  return { success: true, total: allQA.length, normalized: results.filter(r => !r.note).length, batchId, message: `结果已存入 qa_normalize_results/${batchId}` }
}

// ========== 撩一下 v3：AI 语义生成多策略 ==========

async function generateQAByAIV3(content, userId) {
  if (userId) {
    const bal = await checkReplyBalance(userId, QA_GEN_EST_TOKENS * 2)
    if (!bal.ok) return null
  }

  const settingsRes = await db.collection('system_settings').where({ scope: 'global', key: 'ai' }).limit(1).get().catch(() => null)
  const settings = settingsRes?.data?.[0] || {}
  const cfg = getPetSpeakConfig(settings, 'qaStrategy')
  const systemPrompt = cfg.systemPrompt || DEFAULT_PET_SPEAK_CONFIG.qaStrategy.systemPrompt

  const userPrompt = `用户想表达的意思：${content.slice(0, 200)}\n\n从策略库里选2个最合适的，生成话术。`

  return tryWithModelFallback(async (model) => {
    const baseUrl = model.baseUrl.replace(/\/+$/, '')
    const urls = [`${baseUrl}/v1/chat/completions`, `${baseUrl}/chat/completions`]

    for (const url of urls) {
      try {
        const resp = await aiHttpRequest(url, {
          model: model.model,
          messages: [
            { role: 'system', content: systemPrompt },
            { role: 'user', content: userPrompt }
          ],
          temperature: cfg.temperature,
          max_tokens: cfg.maxTokens,
          response_format: { type: 'json_object' }
        }, REPLY_TIMEOUT_MS, model.apiKey)

        if (resp.status === 404) continue
        const data = await resp.json().catch(() => null)
        const raw = data?.choices?.[0]?.message?.content || ''
        const parsed = JSON.parse(raw)

        if (parsed?.lines && Array.isArray(parsed.lines)) {
          const valid = parsed.lines.filter(l =>
            l.type && l.label && l.text && l.text.includes('|') && l.text.split('|').filter(Boolean).length >= 2
          )
          if (valid.length > 0) {
            const realTokens = getUsageTotalTokens(data?.usage, QA_GEN_EST_TOKENS * 2)
            if (userId) await recordPetTokenUsage(userId, realTokens, model.model, data?.usage, PET_QA_USAGE_FEATURE)
            await recordModelTokenUsage(model.id, realTokens, data?.usage)
            const texts = valid.map(l => l.text)
            await updateUserQAHistory(userId, texts, 'ai')
            return { success: true, lines: valid }
          }
        }
        // non-404 non-parseable → try next model
        break
      } catch (e) {
        console.error(`generateQAByAIV3 model ${model.id} error:`, e?.message?.slice(0, 60))
        break // try next model
      }
    }
    return { success: false, message: `模型 ${model.id} 调用失败` }
  }).then(r => r?.success ? r : null)
}

/** 从 seed 里取高分匹配的 QA，按策略去重，保证多样性 */
function pickTopSeedMatches(content, topN = 2, isMinor) {
  const keywords = extractKeywords(content)
  let allQA = SEED_DATA.filter(d => d.category === 'qa')
  if (isMinor) allQA = filterSeedForMinor(allQA)

  const scored = allQA.map(d => {
    let score = 0
    if (keywords.length > 0 && d.tags) {
      score = keywords.filter(kw => d.tags.includes(kw)).length
    }
    return { ...d, score }
  }).sort((a, b) => b.score - a.score)

  // 按策略去重：每种策略最多取 1 条
  const seenStrats = new Set()
  const picks = []
  for (const d of scored) {
    if (d.score < 2) continue
    const strat = d.strategy || 'direct'
    if (!seenStrats.has(strat)) {
      seenStrats.add(strat)
      picks.push(d)
      if (picks.length >= topN) break
    }
  }

  return picks.map(d => ({
    type: 'seed',
    label: d.strategy ? _strategyLabel(d.strategy) : '精选',
    text: d.text,
    score: d.score,
    strategy: d.strategy
  }))
}

function _strategyLabel(s) {
  const m = { contrast: '反转', progressive: '引导', direct: '直球', humor: '幽默', literary: '文艺' }
  return m[s] || '精选'
}

// ========== 批量策略打标 ==========

async function tagQAStrategies(userId) {
  if (!userId) return { success: false, code: 'NO_USER', message: '请先登录' }

  const allQA = SEED_DATA.filter(d => d.category === 'qa')
  if (allQA.length === 0) return { tagged: 0 }

  const settingsRes = await db.collection('system_settings').where({ scope: 'global', key: 'ai' }).limit(1).get().catch(() => null)
  const settings = settingsRes?.data?.[0]
  const ai = normalizeAISettingsForReply(settings || {})
  if (!ai.enabled || !ai.apiKey) return { success: false, message: 'AI 未启用' }

  const systemPrompt = `你是撩人话术分类助手。给每条话术打一个策略标签，五选一：
- contrast（反转）：先推后拉，制造情绪反转
- progressive（引导拉近）：导向亲密动作或见面
- direct（直球夸赞）：直接表白或夸赞，不绕弯
- humor（幽默破冰）：搞笑无厘头，松弛破冰
- literary（文艺情话）：诗意比喻，浪漫氛围

返回 JSON：{"results":[{"index":0,"strategy":"contrast"},...]}`

  const cfg = getPetSpeakConfig(settings || {}, 'lineTagging')
  const BATCH_SIZE = 50
  let done = 0
  const allTagged = []

  for (let start = 0; start < allQA.length; start += BATCH_SIZE) {
    if (userId) {
      const bal = await checkReplyBalance(userId, LINE_TAGGING_EST_TOKENS)
      if (!bal.ok) return { success: false, ...bal, message: bal.message || '余额不足，请先充值', done, tagged: allTagged.length }
    }

    const batch = allQA.slice(start, start + BATCH_SIZE)
    const items = batch.map((d, i) => `${start + i}: ${d.text}`).join('\n')

    const baseUrl = ai.baseUrl.replace(/\/+$/, '')
    const urls = [`${baseUrl}/v1/chat/completions`, `${baseUrl}/chat/completions`]
    let batchDone = false

    for (const url of urls) {
      if (batchDone) break
      try {
        const resp = await aiHttpRequest(url, {
          model: ai.model,
          messages: [
            { role: 'system', content: systemPrompt },
            { role: 'user', content: `给以下话术打策略标签，只返回 JSON：\n${items}` }
          ],
          temperature: cfg.temperature,
          max_tokens: cfg.maxTokens
        }, REPLY_TIMEOUT_MS * 2, ai.apiKey)

        if (resp.status === 404) continue
        const data = await resp.json().catch(() => null)
        const raw = data?.choices?.[0]?.message?.content || ''
        const jsonMatch = raw.match(/\[[\s\S]*\]/)
        if (!jsonMatch) continue

        const parsed = JSON.parse(jsonMatch[0])
        parsed.forEach(item => {
          if (typeof item.index === 'number' && ['contrast','progressive','direct','humor','literary'].includes(item.strategy)) {
            allTagged.push({ index: item.index, strategy: item.strategy })
          }
        })
        if (userId) await recordPetTokenUsage(userId, getUsageTotalTokens(data?.usage, LINE_TAGGING_EST_TOKENS), ai.model, data?.usage, PET_QA_TAGGING_USAGE_FEATURE)
        done += batch.length
        batchDone = true
      } catch (e) {
        console.error(`tagQAStrategies batch ${start} error:`, e?.message?.slice(0, 80))
      }
    }
    console.log(`tagQAStrategies: ${done}/${allQA.length}`)
  }

  // 存到 DB
  const batchId = `qa_strat_${Date.now()}`
  try {
    await db.collection('qa_strategy_tags').add({
      _id: batchId,
      total: allQA.length,
      tagged: allTagged.length,
      results: allTagged,
      createdAt: new Date()
    })
  } catch {}

  return { success: true, total: allQA.length, tagged: allTagged.length, batchId }
}

// ========== 多轮对话策略引擎 ==========

async function generateReplyStrategy(content, userId, scene = 'reply', safetyContext) {
  const settingsRes = await db.collection('system_settings').where({ scope: 'global', key: 'ai' }).limit(1).get().catch(() => null)
  const settings = settingsRes?.data?.[0]
  const ai = normalizeAISettingsForReply(settings || {})
  const cfg = getPetSpeakConfig(settings || {}, 'replyStrategy', safetyContext)
  if (!ai.enabled || !ai.apiKey) return { success: false, message: 'AI 配置未启用或缺少 API Key' }

  if (userId) {
    const strategyAccess = await checkFeatureAccess(db, userId, PET_STRATEGY_ACCESS_FEATURE)
    if (!strategyAccess.allowed) {
      return {
        success: false,
        code: 'FEATURE_NOT_AVAILABLE',
        message: strategyAccess.reason || '当前套餐不支持小咪多轮策略'
      }
    }
    const bal = await checkPetTokenBalance(userId, REPLY_STRATEGY_EST_TOKENS, PET_STRATEGY_ACCESS_FEATURE)
    if (!bal.ok) return { success: false, ...bal, message: bal.message || '余额不足，请充值' }
  }

  const isActiveScene = scene === 'active'
  const isMinor = safetyContext?.isMinor || false
  let systemPrompt = `你是恋爱对话策略教练。${isActiveScene ? '用户想主动问对方或主动表达一个意思，你需要生成2种多轮撩一下策略。' : '对方说了一句话，你需要生成2种多轮对话策略。'}

策略1——先冷后甜（type: "contrast"）：
${isActiveScene ? '第一句先用轻松反转开场，不要直接暴露全部意图；第二句翻转成夸赞或明确邀约，制造一点轻松心动。' : '第一句先轻微否定/调侃对方，让对方产生小情绪甚至有点生气。第二句翻转成夸赞/深情，制造情绪反转，让对方又气又笑。这种推拉制造情绪价值。'}

策略2——${isActiveScene ? '投石问路' : '顺水推舟'}（type: "progressive"）：
${isActiveScene ? '第一句低压力抛出话题（投石问路），第二句根据对方可能回应继续拉近，第三句（可选）顺水推舟引导见面或下一次互动。' : '第一句埋钩子让对方好奇追问，第二句顺水推舟接住对方反应，第三句（可选）继续推进引导见面或更近一步。'}

规则：
- 每句话15-35字，口语化、接地气、不油腻、像真人聊天
- 不要性暗示、不要逼表态、不要情绪勒索、不要装可怜
- expectReactions 列出对方可能的1-3种回复
- note 说明这一步的意图
- 返回严格 JSON，不要任何解释文字

JSON 格式：
{
  "strategies": [
    {
      "type": "contrast",
      "label": "先冷后甜",
      "turns": [
        {"step":1, "say":"话术", "note":"意图说明", "expectReactions":["可能的回复1","可能的回复2"]},
        {"step":2, "say":"话术", "note":"意图说明"}
      ]
    },
    {
      "type": "progressive",
      "label": "${isActiveScene ? '投石问路' : '顺水推舟'}",
      "turns": [
        {"step":1, "say":"话术", "note":"意图说明", "expectReactions":["可能回复"]},
        {"step":2, "say":"话术", "note":"意图说明"},
        {"step":3, "say":"话术", "note":"意图说明", "optional":true}
      ]
    }
  ]
}`

  if (isMinor) {
    systemPrompt = `你是同学关系对话教练。用户未满 18 岁。\n只允许友谊、校园社交、边界感和健康沟通建议。\n不要生成暧昧、撩拨、性暗示或引导亲密关系升级的对话。\n所有话术应符合同学/朋友的交流尺度。\n\n` + systemPrompt
  } else if (safetyContext?.boundarySensitive) {
    systemPrompt = `【边界提醒】当前对话涉及敏感话题。不要替用户同意任何行为，优先提醒尊重、节奏和安全。\n\n` + systemPrompt
  }

  const userPrompt = isActiveScene
    ? `用户想主动表达：${content.slice(0, 300)}\n\n请生成"先冷后甜"和"投石问路"两种多轮策略。`
    : `对方说的话：${content.slice(0, 300)}\n\n请生成"先冷后甜"和"顺水推舟"两种多轮策略。`

  const baseUrl = ai.baseUrl.replace(/\/+$/, '')
  const urls = [`${baseUrl}/v1/chat/completions`, `${baseUrl}/chat/completions`]

  for (const url of urls) {
    try {
      const resp = await aiHttpRequest(url, {
        model: ai.model,
        messages: [
          { role: 'system', content: systemPrompt },
          { role: 'user', content: userPrompt }
        ],
        temperature: cfg.temperature,
        max_tokens: cfg.maxTokens,
        response_format: { type: 'json_object' }
      }, REPLY_TIMEOUT_MS, ai.apiKey)

      if (resp.status === 404) continue
      const data = await resp.json().catch(() => null)
      const raw = data?.choices?.[0]?.message?.content || ''
      const parsed = JSON.parse(raw)

      if (parsed?.strategies && Array.isArray(parsed.strategies)) {
        const valid = parsed.strategies.filter(s =>
          s.type && s.label && Array.isArray(s.turns) && s.turns.length >= 2
        )
        if (valid.length > 0) {
          if (userId) await recordPetTokenUsage(userId, getUsageTotalTokens(data?.usage, REPLY_STRATEGY_EST_TOKENS), ai.model, data?.usage, PET_STRATEGY_USAGE_FEATURE)
          return { success: true, strategies: valid }
        }
      }
    } catch (e) {
      console.error('generateReplyStrategy error:', e?.message?.slice(0, 100))
    }
  }

  return { success: false, message: 'AI 生成策略失败，请重试' }
}

// ========== exports ==========

exports.main = async (event = {}) => {
  const action = event.action || 'random'
  try {
    switch (action) {
      case 'seed': {
        return { success: false, message: 'seed is disabled' }
      }
      case 'random': {
        const line = await getRandomLine(event.category)
        if (!line) return { success: false, message: '话术库暂无数据' }
        return { success: true, line }
      }
      case 'randomPair': {
        const [humor, literary] = await Promise.all([getRandomLine('humor'), getRandomLine('literary')])
        return { success: true, humor, literary }
      }
      case 'reply': {
        const eventDesc = String(event.eventDescription || event.desc || '').trim()
        if (!eventDesc || eventDesc.length < 4) return { success: false, message: '请提供事件描述（至少4个字）' }
        const eventType = ['positive', 'risk', 'verification', 'note'].includes(event.eventType) ? event.eventType : 'note'
        let userId
        try {
          userId = await requirePetUserId(event)
        } catch (error) {
          const authError = buildAuthErrorResponse(error)
          if (authError) return authError
          throw error
        }
        let isMinor = false
        if (userId) { const profile = await fetchUserSelfProfile(userId); isMinor = profile?.ageRange === 'under18' }
        return await generateReply(eventDesc, eventType, userId, isMinor)
      }
      case 'replyStrategy': {
        const strategyContent = String(event.content || '').trim()
        const strategyScene = event.scene === 'active' ? 'active' : 'reply'
        if (!strategyContent || strategyContent.length < 1) return { success: false, message: strategyScene === 'active' ? '请输入想表达的内容' : '请输入对方说的话' }
        let sUserId
        try {
          sUserId = await requirePetUserId(event)
        } catch (error) {
          const authError = buildAuthErrorResponse(error)
          if (authError) return authError
          throw error
        }
        let safetyContext = { isMinor: false, boundarySensitive: false }
        if (sUserId) {
          const profile = await fetchUserSelfProfile(sUserId)
          const isMinor = profile?.ageRange === 'under18'
          safetyContext = { isMinor, boundarySensitive: !isMinor && isBoundarySensitivePromptEvent(strategyContent) }
        }
        return await generateReplyStrategy(strategyContent, sUserId, strategyScene, safetyContext)
      }
      case 'replyPair': {
        const scene = event.scene === 'active' ? 'active' : 'reply'
        const content = String(event.content || '').trim()
        const tone = String(event.tone || '').trim()
        if (!content || content.length < 1) return { success: false, message: '请输入内容' }
        let userId
        try {
          userId = await requirePetUserId(event)
        } catch (error) {
          const authError = buildAuthErrorResponse(error)
          if (authError) return authError
          throw error
        }
        let safetyContext = { isMinor: false, boundarySensitive: false }
        if (userId) {
          const profile = await fetchUserSelfProfile(userId)
          const isMinor = profile?.ageRange === 'under18'
          safetyContext = { isMinor, boundarySensitive: !isMinor && isBoundarySensitivePromptEvent(content) }
        }
        return await generateReplyPair(scene, content, userId, tone, safetyContext)
      }
      case 'replyBundle': {
        const scene = event.scene === 'active' ? 'active' : 'reply'
        const content = String(event.content || '').trim()
        if (!content || content.length < 1) return { success: false, message: '请输入内容' }
        let userId
        try {
          userId = await requirePetUserId(event)
        } catch (error) {
          const authError = buildAuthErrorResponse(error)
          if (authError) return authError
          throw error
        }
        let safetyContext = { isMinor: false, boundarySensitive: false }
        if (userId) {
          const profile = await fetchUserSelfProfile(userId)
          const isMinor = profile?.ageRange === 'under18'
          safetyContext = { isMinor, boundarySensitive: !isMinor && isBoundarySensitivePromptEvent(content) }
        }
        const [pairRes, stratRes] = await Promise.all([
          generateReplyPair(scene, content, userId, '', safetyContext).catch((e) => ({ success: false, message: e?.message || 'reply 失败' })),
          generateReplyStrategy(content, userId, scene, safetyContext).catch((e) => ({ success: false, message: e?.message || 'strategy 失败' }))
        ])
        if (isTokenBalanceError(pairRes)) return pairRes
        if (isTokenBalanceError(stratRes)) return stratRes
        if (stratRes && stratRes.code === 'FEATURE_NOT_AVAILABLE') return stratRes
        if (!pairRes?.success) {
          return { success: false, ...pairRes, message: pairRes?.message || '生成失败，请重试' }
        }
        return {
          success: true,
          variants: pairRes.variants || {},
          reply: pairRes.reply,
          alternative: pairRes.alternative,
          inspirations: pairRes.inspirations,
          tokensUsed: pairRes.tokensUsed,
          strategies: stratRes?.success ? (stratRes.strategies || []) : []
        }
      }
      case 'pickQA': {
        const content = String(event.content || '').trim()
        if (!content) return { success: false, message: '请输入内容' }
        const keywords = extractKeywords(content)
        let userId
        try {
          userId = await requirePetUserId(event)
        } catch (error) {
          const authError = buildAuthErrorResponse(error)
          if (authError) return authError
          throw error
        }
        let isMinor = false
        if (userId) { const profile = await fetchUserSelfProfile(userId); isMinor = profile?.ageRange === 'under18' }
        const lines = pickRandomLines(2, 'qa', keywords, isMinor)
        return { success: true, lines: lines.map(l => ({ text: l.text })) }
      }
      case 'pickQA_v3': {
        const v3Content = String(event.content || '').trim()
        if (!v3Content) return { success: false, message: '请输入内容' }
        let v3UserId
        try {
          v3UserId = await requirePetUserId(event)
        } catch (error) {
          const authError = buildAuthErrorResponse(error)
          if (authError) return authError
          throw error
        }
        let isMinor = false
        if (v3UserId) { const profile = await fetchUserSelfProfile(v3UserId); isMinor = profile?.ageRange === 'under18' }

        const lines = []

        // 1. 先从 seed 取高分匹配（关键词命中 >= 2），未成年过滤暧昧内容
        const seedMatches = pickTopSeedMatches(v3Content, 2, isMinor)
        seedMatches.forEach(m => lines.push(m))

        // 2. AI 生成策略
        const aiResult = await generateQAByAIV3(v3Content, v3UserId)
        if (aiResult?.success && aiResult.lines?.length > 0) {
          aiResult.lines.forEach(l => lines.push(l))
        }

        // 3. 如果什么都没有，回退 v2
        if (lines.length === 0) {
          const fbResult = await pickQAWithDedup(v3Content, v3UserId)
          return { success: true, ...fbResult, fallback: true }
        }

        // 记录 seed 匹配的到去重历史
        const seedTexts = seedMatches.map(m => m.text)
        if (seedTexts.length > 0) {
          await updateUserQAHistory(v3UserId, seedTexts, 'seed')
        }

        return { success: true, lines }
      }
      case 'pickQA_v2': {
        const content = String(event.content || '').trim()
        if (!content) return { success: false, message: '请输入内容' }
        let userId
        try {
          userId = await requirePetUserId(event)
        } catch (error) {
          const authError = buildAuthErrorResponse(error)
          if (authError) return authError
          throw error
        }
        const result = await pickQAWithDedup(content, userId)
        return { success: true, ...result }
      }
      case 'tagQAStrategies': {
        return { success: false, message: 'tagQAStrategies is disabled' }
      }
      case 'tagLines': {
        return { success: false, message: 'tagLines is disabled' }
      }
      case 'normalizeQASelfReply': {
        return { success: false, message: 'normalizeQASelfReply is disabled' }
      }
      case 'count': {
        const { total } = await db.collection(COLLECTION).count()
        const [humorRes, literaryRes, qaRes] = await Promise.all([
          db.collection(COLLECTION).where({ category: 'humor' }).count(),
          db.collection(COLLECTION).where({ category: 'literary' }).count(),
          db.collection(COLLECTION).where({ category: 'qa' }).count()
        ])
        return { success: true, total, humor: humorRes.total, literary: literaryRes.total, qa: qaRes.total }
      }
      default: return { success: false, message: `未知操作: ${action}` }
    }
  } catch (error) {
    console.error('petLines error:', error)
    return { success: false, message: error.message || '操作失败' }
  }
}
